css:
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes fadeOut{to{opacity:0}}
@keyframes rise{from{opacity:0;transform:translateY(50px)}to{opacity:1;transform:none}}
@keyframes riseBlur{from{opacity:0;transform:translateY(60px);filter:blur(16px)}to{opacity:1;transform:none;filter:blur(0)}}
@keyframes liftOut{to{opacity:0;transform:translateY(-120px) scale(.94);filter:blur(14px)}}
@keyframes pop{0%{opacity:0;transform:scale(0) rotate(-120deg)}70%{opacity:1;transform:scale(1.1) rotate(6deg)}100%{opacity:1;transform:none}}
@keyframes wipe{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 -10% 0 0)}}
@keyframes drift{0%{transform:translate(0,0) scale(1)}50%{transform:translate(140px,-90px) scale(1.18)}100%{transform:translate(-70px,70px) scale(.94)}}
@keyframes sweep{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.bg{overflow:hidden}
.orb{position:absolute;border-radius:50%;filter:blur(120px);animation:drift 24s ease-in-out 0s both}
.grid{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);background-size:80px 80px;-webkit-mask-image:radial-gradient(ellipse at center,#000 30%,transparent 75%);mask-image:radial-gradient(ellipse at center,#000 30%,transparent 75%)}
.shot{position:absolute;border-radius:22px;overflow:hidden;border:1px solid rgba(255,255,255,.12);box-shadow:0 50px 140px rgba(0,0,0,.65),0 0 0 1px rgba(0,0,0,.4)}
.shot img{display:block;width:100%;height:100%;object-fit:cover;object-position:top left}
.h{font-family:var(--font-headline);font-weight:900;letter-spacing:-.045em;line-height:.95;color:var(--fg);margin:0}
.p{font-size:38px;color:var(--muted);line-height:1.35;margin:0}

.mbg{background:radial-gradient(ellipse at 30% 0%,#2A1440 0%,var(--bg) 60%)}
.o1{width:760px;height:760px;background:#FF5C7A;right:-200px;top:-280px;opacity:.24}
.o2{width:760px;height:760px;background:#8B5CF6;left:-260px;bottom:-300px;opacity:.28;animation-direction:reverse;animation-duration:20s}

.ed{animation:liftOut .6s cubic-bezier(.7,0,.84,0) 4.9s forwards}
.mon{position:absolute;left:460px;top:90px;width:1000px;height:562px;border-radius:24px;background:#000;border:1px solid rgba(255,255,255,.12);overflow:hidden;box-shadow:0 40px 120px rgba(0,0,0,.6);animation:riseBlur .8s cubic-bezier(.16,1,.3,1) 0s both}
.mon .say{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:150px;opacity:0}
.mon .s1{animation:sayIn .4s cubic-bezier(.16,1,.3,1) .5s both,fadeOut .2s ease 1.9s forwards;background:radial-gradient(circle at 30% 30%,#3A1530,#000 70%)}
.mon .s2{animation:sayIn .4s cubic-bezier(.16,1,.3,1) 2.1s both,fadeOut .2s ease 3.4s forwards;background:radial-gradient(circle at 70% 40%,#1B1A4A,#000 70%)}
.mon .s3{animation:sayIn .4s cubic-bezier(.16,1,.3,1) 3.6s both;background:radial-gradient(circle at 50% 60%,#45122A,#000 70%);color:var(--accent)}
@keyframes sayIn{from{opacity:0;transform:scale(1.4);letter-spacing:.1em}to{opacity:1;transform:none}}
.tl{position:absolute;left:160px;right:160px;top:720px;height:260px;border-radius:22px;background:rgba(24,19,42,.9);border:1px solid rgba(255,255,255,.08);animation:rise .8s cubic-bezier(.16,1,.3,1) .15s both;overflow:hidden}
.ruler{position:absolute;left:24px;right:24px;top:16px;height:24px;background:repeating-linear-gradient(90deg,rgba(255,255,255,.18) 0 2px,transparent 2px 64px)}
.lane{position:absolute;left:24px;right:24px;height:52px}
.blk{position:absolute;top:0;bottom:0;border-radius:12px;transform-origin:left;animation:sweep .6s cubic-bezier(.16,1,.3,1) both}
.ph{position:absolute;top:8px;bottom:8px;width:4px;margin-left:-2px;background:#fff;border-radius:2px;box-shadow:0 0 18px #fff;animation:play 4.4s linear .5s both}
.ph::before{content:"";position:absolute;left:-12px;top:-4px;width:28px;height:18px;border-radius:6px;background:#fff}
@keyframes play{from{left:24px}to{left:calc(100% - 24px)}}

.ask{animation:fadeOut .5s ease 5.5s forwards}
.ask .copy{position:absolute;left:130px;top:300px;width:640px}
.ask .h{font-size:104px;animation:riseBlur .9s cubic-bezier(.16,1,.3,1) .1s both}
.ask .h em{font-style:normal;background:linear-gradient(90deg,#FF5C7A,#FF8A5C,#8B5CF6);-webkit-background-clip:text;background-clip:text;color:transparent}
.ask .p{margin-top:30px;animation:rise .8s cubic-bezier(.16,1,.3,1) .45s both}
.ask .shot{left:820px;top:140px;width:1280px;height:720px;animation:tiltIn 1.3s cubic-bezier(.16,1,.3,1) 0s both}
.ask .shot img{transform-origin:40% 38%;animation:kbm 5.2s ease-in-out 1s both}
@keyframes tiltIn{from{opacity:0;transform:perspective(2600px) rotateY(-36deg) translateX(300px) scale(.9)}to{opacity:1;transform:perspective(2600px) rotateY(-13deg)}}
@keyframes kbm{from{transform:scale(1)}to{transform:scale(1.45)}}

.trio{animation:fadeOut .5s ease 5s forwards}
.trio .top{position:absolute;left:0;right:0;top:70px;text-align:center}
.trio .h{font-size:92px;animation:riseBlur .8s cubic-bezier(.16,1,.3,1) .05s both}
.trio .shot{width:860px;height:484px;top:330px}
.trio .a{left:60px;animation:fanL 1.1s cubic-bezier(.16,1,.3,1) .3s both}
.trio .b{left:530px;top:290px;z-index:2;width:860px;animation:fanC 1.1s cubic-bezier(.16,1,.3,1) .5s both}
.trio .c{right:60px;animation:fanR 1.1s cubic-bezier(.16,1,.3,1) .7s both}
@keyframes fanL{from{opacity:0;transform:translateY(200px) rotate(0)}to{opacity:1;transform:perspective(2000px) rotateY(18deg) rotate(-3deg)}}
@keyframes fanC{from{opacity:0;transform:translateY(240px) scale(.9)}to{opacity:1;transform:scale(1.04)}}
@keyframes fanR{from{opacity:0;transform:translateY(200px)}to{opacity:1;transform:perspective(2000px) rotateY(-18deg) rotate(3deg)}}
.labels{position:absolute;left:0;right:0;top:880px;display:flex;justify-content:center;gap:280px;font-size:36px;font-weight:700;color:var(--fg)}
.labels span{animation:rise .6s cubic-bezier(.16,1,.3,1) both}
.labels span i{font-style:normal;color:var(--accent);margin-right:12px}

.any{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;animation:fadeOut .45s ease 3.7s forwards}
.any .row{font-size:170px;font-weight:900;letter-spacing:-.05em;display:flex}
.any .bl{display:inline-block;animation:bounce .8s cubic-bezier(.34,1.56,.64,1) both}
@keyframes bounce{0%{opacity:0;transform:translateY(-200px) rotate(-25deg) scale(.4)}100%{opacity:1;transform:none}}
.any .sp{display:inline-block;animation:spin .9s cubic-bezier(.16,1,.3,1) both}
@keyframes spin{from{opacity:0;transform:rotateY(270deg) scale(2)}to{opacity:1;transform:none}}
.any .row.g{background:linear-gradient(90deg,#FF5C7A,#FF8A5C 40%,#8B5CF6);-webkit-background-clip:text;background-clip:text;color:transparent}
.any .p{font-size:42px;margin-top:40px;animation:rise .7s cubic-bezier(.16,1,.3,1) 1.8s both}

.end{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:40px}
.logo{display:flex;align-items:center;gap:44px}
.mark{width:200px;height:200px;border-radius:52px;background:linear-gradient(135deg,#FF5C7A,#C94BD8 55%,#8B5CF6);display:grid;place-items:center;color:#fff;animation:pop 1s cubic-bezier(.16,1,.3,1) .15s both}
.word{font-size:210px;font-weight:900;letter-spacing:-.06em;color:var(--fg);animation:wipe 1s cubic-bezier(.7,0,.2,1) .7s both}
.end .p{font-size:46px;animation:rise .8s cubic-bezier(.16,1,.3,1) 1.5s both}
